window.PFB_NEW = {"title": "New in the fridge", "showFrom": "2026-12-02T00:00:00Z", "slots": [{"n": 17, "stage": "teaser", "launch": "2026-12-15", "name": "Jelly Wobble", "kind": "Volume shaper", "line": "Draw a wobble and it pumps your track in time, like sidechain ducking you can shape."}, {"n": 18, "stage": "hidden"}, {"n": 19, "stage": "hidden"}, {"n": 20, "stage": "hidden"}, {"n": 21, "stage": "hidden"}]};
